import { describe, test, expect } from 'vitest';
import { render, fireEvent, waitFor } from '@testing-library/react';
import '@testing-library/jest-dom';
import React from 'react';
import App from '../src/App';

const tick = (ms = 20) => new Promise((resolve) => setTimeout(resolve, ms));

describe('Portals', () => {
  test('Has an Open Modal button', async () => {
    const { container: root } = render(<App />);
    const btn = root.querySelector('#open-modal');
if (!btn) throw new Error('No button with id "open-modal" found');
if (document.querySelector('#modal'))
  throw new Error('Modal should not render before the button is clicked');
  });

  test('Clicking Open renders the modal outside #root', async () => {
    const { container: root } = render(<App />);
    root.querySelector('#open-modal').click();
await tick();
const modal = document.querySelector('#modal');
if (!modal) throw new Error('Expected element with id "modal" after opening');
if (root.contains(modal))
  throw new Error('Modal should be portaled OUT of #root (still inside it)');
  });

  test('Close button removes the modal', async () => {
    const { container: root } = render(<App />);
    const close = document.querySelector('#close-modal');
if (!close) throw new Error('No close button with id "close-modal" found');
close.click();
await tick();
if (document.querySelector('#modal'))
  throw new Error('Modal should be removed after clicking Close');
  });
});
